<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$done=[];$errors=[];if($pdo&&$_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$pdo->exec('CREATE TABLE IF NOT EXISTS schema_migrations(version VARCHAR(80) PRIMARY KEY,applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');$migrations=['001_add_featured_image'=>'ALTER TABLE articles ADD COLUMN featured_image VARCHAR(500) NULL AFTER category'];foreach($migrations as $version=>$sql){$s=$pdo->prepare('SELECT 1 FROM schema_migrations WHERE version=?');$s->execute([$version]);if($s->fetchColumn())continue;try{$pdo->exec($sql);}catch(Throwable $e){if(stripos($e->getMessage(),'duplicate column')===false)throw $e;}$pdo->prepare('INSERT INTO schema_migrations(version) VALUES(?)')->execute([$version]);$done[]=$version;}}catch(Throwable $e){$errors[]='Migration failed.';}}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Database Migration</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><section class="card"><h1>Database Migration</h1><?php foreach($done as $v):?><p role="status">Applied <?=e($v)?></p><?php endforeach;?><?php foreach($errors as $v):?><p role="alert"><?=e($v)?></p><?php endforeach;?><p>Run migrations only after taking a database backup.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><button>Run migrations</button></form></section></main></body></html>
